pcall(function()
    if not (hookmetamethod and getnamecallmethod) then return end
    local cc = checkcaller or function() return false end
    local old
    old = hookmetamethod(game, "__namecall", (newcclosure or function(f) return f end)(function(self, ...)
        if RUNNING and self == MarketplaceService and not cc() and on("pr_robux") then
            local m = getnamecallmethod()
            if type(m) == "string" and m:sub(1, 6) == "Prompt" then return nil end
        end
        return old(self, ...)
    end))
    onClean(function() pcall(hookmetamethod, game, "__namecall", old) end)
end)
task.spawn(F.streamer)
task.spawn(function()
    while RUNNING do
        local ok, err = pcall(function()
            FR.tick()
            P.tick()
            ST.progress()
            local did = false
            if on("eg_auto") and not attr("holdingFriend") then
                local d = G.data()
                if d then
                    if os.clock() >= (F.idleUntil or 0) then
                        local c = F.candidates(d)[1]
                        if c then F.trip(c); did = true; task.wait(0.2); P.tick() else F.idleUntil = os.clock() + 1 end
                    end
                end
            end
            if not did then
                ST.bench()
                if not S.busy then S.task = attr("Benching") and L["Training"] or (on("eg_auto") and L["Waiting for eggs"] or L["Idle"]) end
            end
        end)
        if not ok then say(L["Error: "] .. tostring(err):sub(1, 60)) end
        task.wait(on("eg_auto") and 0.3 or 1)
    end
end)
task.spawn(function()
    while RUNNING do
        if getgenv().Library ~= Library then getgenv().Library = Library end
        local d = G.data()
        if d then
            S.str0 = S.str0 or d.strength or 0
            local slots = P.slots(d)
            local used, eggs = 0, 0
            for _, p in pairs(d.plotPets or {}) do used = used + 1; if p.hatchAt then eggs = eggs + 1 end end
            setText(UI.status, os.clock() - S.msgAt < 4 and S.msg or S.task)
            setText(UI.stats1, string.format(L["Eggs %d · Trips %d · Lost %d"], S.eggs, S.trips, S.lost))
            setText(UI.stats2, string.format(L["Plot %d/%d · Hatching %d · $%s/s"], used, slots, eggs, short(attr("IncomePerSec", 0))))
            local nxt = G.Reb[(d.rebirths or 0) + 1]
            local mins = math.max(1 / 60, (os.clock() - S.t0) / 60)
            setText(UI.stats3, string.format(L["Str %s · +%s/min%s"], short(d.strength or 0), short(((d.strength or 0) - S.str0) / mins), nxt and (L[" · Reb "] .. short(nxt.StrengthRequirement)) or ""))
        end
        task.wait(0.5)
    end
end)
